<template><main class="store-shell py-5"><header class="store-card p-4 mb-4"><span class="store-eyebrow">Help center</span><h1 class="store-title">Support tickets</h1></header><section class="row g-4"><div class="col-lg-5"><form class="store-card p-4" @submit.prevent="create"><h2 class="h4">Create ticket</h2><input v-model="form.subject" class="store-input form-control mb-3" placeholder="Subject" required><select v-model="form.priority" class="store-input form-select mb-3"><option v-for="p in priorities" :key="p">{{p}}</option></select><textarea v-model="form.message" class="store-input form-control mb-3" rows="6" placeholder="How can we help?" required></textarea><button class="store-btn store-btn--primary">Submit</button></form></div><div class="col-lg-7"><div class="store-card p-4"><h2 class="h4">Your tickets</h2><RouterLink v-for="t in tickets" :key="t.id" :to="`/${lang}/support/${t.id}`" class="d-flex justify-content-between border-bottom py-3 text-decoration-none"><span><strong>{{t.ticket_number}}</strong><br>{{t.subject}}</span><span>{{t.status}}</span></RouterLink></div></div></section></main></template>
<script setup>
import {computed,onMounted,reactive,ref} from "vue"; import {RouterLink,useRoute,useRouter} from "vue-router"; import {useSeoMeta} from "@/composables/useSeoMeta"; import service from "@/services/home/TicketService";
const route=useRoute(),router=useRouter(),lang=computed(()=>route.params.lang||"en"),tickets=ref([]),priorities=["low","normal","high","urgent"],form=reactive({subject:"",priority:"normal",message:""}); useSeoMeta({title:"Support",robots:"noindex,nofollow"});
const load=async()=>tickets.value=(await service.list()).data?.data||[]; const create=async()=>{const ticket=(await service.create(form)).data;router.push(`/${lang.value}/support/${ticket.id}`)}; onMounted(load);
</script>
